import { createFeatureSelector, createSelector } from '@ngrx/store';
import { AttemptsReducer } from '../';

const attemptsState = createFeatureSelector<AttemptsReducer.AttemptsState>(AttemptsReducer.actionReducerAttemptsKey);

export const attempts = createSelector(
  attemptsState,
  ({ attempts }) => attempts
);

export const canTry = createSelector(
  attempts,
  ( attempts ) =>  attempts < 3
);

export const otpAttempts = createSelector(
  attemptsState,
  ({ otpAttempts }) => otpAttempts
);

export const canTryOtp = createSelector(
  otpAttempts,
  ( otpAttempts ) => otpAttempts < 3
)
