import { Injectable } from '@angular/core';
import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Store } from '@ngrx/store';
import { Router } from '@angular/router';
import { TokenActions } from '../store';

@Injectable()
export class InactivityInterceptor implements HttpInterceptor {

  private readonly INACTIVITY_TIMEOUT = 10 * 60 * 1000;
  private inactivityTimer: any;

  constructor(private store: Store, private router: Router) {
    this.resetTimer(); 
    this.startListening();
  }

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    this.resetTimer(); 
    return next.handle(req).pipe(
      tap({
        error: () => this.resetTimer()
      })
    );
  }

  private startListening() {
    const events = ['mousemove', 'keydown', 'click', 'touchstart'];
    events.forEach(event => {
      window.addEventListener(event, () => this.resetTimer());
    });
  }

  private resetTimer() {
    clearTimeout(this.inactivityTimer);
    this.inactivityTimer = setTimeout(() => this.handleInactivity(), this.INACTIVITY_TIMEOUT);
  }

  private handleInactivity() {
    this.store.dispatch( TokenActions.removeToken() );
    this.router.navigate(['/verify-identity']);
  }

}
