import { createReducer, on } from '@ngrx/store';
import { LoaderActions } from '..';

export const actionReducerLoaderKey: string = 'loader';

export interface LoaderState {
  isLoading: boolean;
}

export const initLoaderState: LoaderState = {
  isLoading: false
} 

export const loaderReducer = createReducer(
  initLoaderState,
  on( LoaderActions.showLoader, state => ({ ...state, isLoading: true })),
  on( LoaderActions.hideLoader, state => ({ ...state, isLoading: false }))
);