import { Injectable } from '@angular/core';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { GlobalDialogComponent } from '../components/global-dialog/global-dialog.component';
import { Observable } from 'rxjs';
import { GlobalDialog } from '../interface';
import { LoaderComponent } from '../components/loader/loader.component';

@Injectable({
  providedIn: 'root'
})
export class DialogService {

  constructor( private dialog: MatDialog ) {}

  openDialog( data: GlobalDialog ): Observable<boolean> {
    const dialogRef = this.dialog.open<GlobalDialogComponent>(GlobalDialogComponent, {
      data,
      width: '400px',
      disableClose: true,
      hasBackdrop: true
    });

    return dialogRef.afterClosed();
  }

  openLoader(): MatDialogRef<LoaderComponent, any> {
    return this.dialog.open<LoaderComponent>(LoaderComponent, {
      width: '200px',
      disableClose: true,
      backdropClass: 'blurred-backdrop',
      panelClass: 'transparent-dialog-panel',
      hasBackdrop: true
    });
  }

}
