import { createAction, props } from '@ngrx/store';

// Client validation attemps
export const loadAttempts = createAction('[Attempts] Load Attempts');
export const attemptsLoaded = createAction('[Attempts] Attempts Loaded', props<{ attempts: number }>());
export const incremetAttempts = createAction('[Attempts] Attempts Increment');
export const resetAttempts = createAction('[Attempts] Reset Attempts');

// OTP validation attemps
export const incrementOtpAttempts = createAction('[OTP Attempts] Increment OTP Attempts');
export const resetOtpAttempts = createAction('[OTP Attempts] Reset OTP Attempts');
