import { createAction, props } from '@ngrx/store';
import { MaskedCustomerInfo } from '../../interfaces';

export const loadUserInfo = createAction(
  '[Verify Identity] Load User Info',
  props<{ identification: string; birthdate: string }>()
);

export const loadUserInfoSuccess = createAction(
  '[Verify Identity] Load User Info Success',
  props<{ customer: MaskedCustomerInfo }>()
);

export const loadUserInfoFailure = createAction(
  '[Verify Identity] Load User Info Failure',
  props<{ error: string }>()
);

export const resetError = createAction(
  '[Verify Identity] Reset Error'
);

export const sendCode = createAction(
  '[Verify Identity] Send OTP Code'
)

export const successSendCode = createAction(
  '[Verify Identity] Success Send OTP Code'
)

export const validateOtpCode = createAction(
  '[Verify Identity] Validate OTP Code',
  props<{ otpCode: string }>()
)

export const resetUserInfo = createAction(
  '[Verify Identity] Clear User Info',
);

