import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class LocalStorageService {

  readonly attemptsStorageKey: string = 'attemptsData';
  readonly tokenStorageKey: string = 'userInfo';

  constructor() {}

  saveToLocalStorage( key: string, data: any ) {
    localStorage.setItem(key, JSON.stringify(data));
  }

  getLocalStorageFromKey( key: string, isJSON: boolean ) {
    return isJSON ? JSON.parse( localStorage.getItem(key)! ) : localStorage.getItem(key)
  }

  getObsLocalStorageFromKey( key: string, isJSON: boolean ): Observable<any | null> {
    return isJSON ? of(JSON.parse( localStorage.getItem(key)! )) : of(localStorage.getItem(key));
  }

  removeItemLocalStorage( key: string ) {
    return localStorage.removeItem( key );
  }

}
