import { createReducer, on } from '@ngrx/store';
import { TokenActions } from '../../../shared/store';

export const actionReducerTokenKey: string = 'token';

export interface TokenState {
  token: string | null;
}

export const initTokenState: TokenState = {
  token: null
}

export const tokenReducer = createReducer(
  initTokenState,
  on( TokenActions.checkToken, ( state ) => ({ ...state })),
  on( TokenActions.saveToken, ( state, { token }) => ({ ...state, token })),
  on( TokenActions.removeToken, state => ({ ...state, token: null }))
);
