import { createFeatureSelector, createSelector } from '@ngrx/store';
import { CustomerReducer } from '..';

const customerSelector = createFeatureSelector<CustomerReducer.CustomerState>(CustomerReducer.actionReducerCustomerKey);

export const customer = createSelector(
  customerSelector,
  ({ customer }) => customer
);

export const error = createSelector(
  customerSelector,
  ({ error }) => error
);

export const hasError = createSelector(
  customerSelector,
  ({ error }) => error !== null
);
