import { createFeatureSelector, createSelector } from "@ngrx/store";
import { InsuredReducer } from "..";

export const insuredSelector = createFeatureSelector<InsuredReducer.InsuredState>(InsuredReducer.insuredActionReducerKey);

export const customer = createSelector(
  insuredSelector,
  ({ customer }) => customer
);

export const maximumProtectionInsurance = createSelector(
  insuredSelector,
  ({ maximumProtectionInsurance }) => maximumProtectionInsurance
);

export const familyLifeInsurance = createSelector(
  insuredSelector,
  ({ familyLifeInsurance }) => familyLifeInsurance
);

export const xsInsurance = createSelector(
  insuredSelector,
  ({ xsInsurance }) => xsInsurance
);

export const oncologicalInsurance = createSelector(
  insuredSelector,
  ({ oncologicalInsurance }) => oncologicalInsurance
);

export const sapInsurance = createSelector(
  insuredSelector,
  ({ sapInsurance }) => sapInsurance
);

export const error = createSelector(
  insuredSelector,
  ({ error }) => error
)
