import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { LogoComponent } from './components/logo/logo.component';
import { GlobalDialogComponent } from './components/global-dialog/global-dialog.component';
import { MaterialModule } from '../material/material.module';
import { StoreModule } from '@ngrx/store';
import { LoaderReducer, TokenReducer } from './store';
import { LoaderComponent } from './components/loader/loader.component';
import { HTTP_INTERCEPTORS } from '@angular/common/http';
import { LoadingInterceptor } from './interceptors/loading.interceptor';
import { EffectsModule } from '@ngrx/effects';
import { TokenEffects } from './store/effects/token.effects';
import { ToolbarComponent } from './components/toolbar/toolbar.component';
import { InfoUserComponent } from './components/info-user/info-user.component';
import { RouterModule } from '@angular/router';
import { TitleCardComponent } from './components/title-card/title-card.component';
import { SidenavComponent } from './components/sidenav/sidenav.component';
import { HeaderInterceptor } from './interceptors/header.interceptor';
import { DisablePasteDirective } from './directives/disable-paste.directive';
import { RestrictInputDirective } from './directives/restrict-input.directive';
import { NotFoundComponent } from './components/not-found/not-found.component';
import { InactivityInterceptor } from './interceptors/Inactivity.interceptor';


@NgModule({
  declarations: [
    LogoComponent,
    GlobalDialogComponent,
    LoaderComponent,
    ToolbarComponent,
    InfoUserComponent,
    TitleCardComponent,
    SidenavComponent,
    DisablePasteDirective,
    RestrictInputDirective,
    NotFoundComponent
  ],
  exports: [
    LogoComponent,
    ToolbarComponent,
    TitleCardComponent,
    NotFoundComponent,
    DisablePasteDirective,
    RestrictInputDirective
  ],
  imports: [
    CommonModule,
    RouterModule,
    MaterialModule,
    StoreModule.forFeature(LoaderReducer.actionReducerLoaderKey, LoaderReducer.loaderReducer),
    StoreModule.forFeature(TokenReducer.actionReducerTokenKey, TokenReducer.tokenReducer),
    EffectsModule.forFeature([ TokenEffects ])
  ],
  providers: [
    { provide: HTTP_INTERCEPTORS, useClass: HeaderInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: LoadingInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: InactivityInterceptor, multi: true }
  ]
})
export class SharedModule { }
