import { createReducer, on } from '@ngrx/store';
import { MaskedCustomerInfo } from '../../interfaces';
import { CustomerActions } from '..';

export const actionReducerCustomerKey: string = 'customer';

export interface CustomerState {
  customer: MaskedCustomerInfo | null;
  error: string | null;
}

const initCustomerState: CustomerState = {
  customer: null,
  error: null
}

export const customerReducer = createReducer(
  initCustomerState,
  on( CustomerActions.loadUserInfo, ( state ) => ({ ...state })),
  on( CustomerActions.loadUserInfoSuccess, ( state, { customer } ) => ({ ...state, customer })),
  on( CustomerActions.loadUserInfoFailure, ( state, { error } ) => ({ ...state, error })),
  on( CustomerActions.resetError, ( state ) => ({ ...state, error: null })),
  on( CustomerActions.sendCode, ( state ) => ({ ...state })),
  on( CustomerActions.successSendCode, ( state ) => ({ ...state })),
  on( CustomerActions.validateOtpCode, ( state ) => ({ ...state })),
  on( CustomerActions.resetUserInfo, ( state ) => ({ ...state, customer: null  })),
);
