import { Injectable } from '@angular/core';
import { BaseResponse, InitApp } from '../interface';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../environments/environment';
import { tap } from 'rxjs';
import { Store } from '@ngrx/store';
import { AttemptsActions } from 'src/app/verify-identity/store';

@Injectable({
  providedIn: 'root'
})
export class InitAppService {

  private baseApiUrl = environment.API_ENDPOINT + environment.INSURANCE_AUTH_API;
  private constants_: InitApp = { attemptsAllowed: 3, inactivationTimeSeconds: 3600 };

  constructor(private httpClient: HttpClient, private store: Store) {}

  get constants(): InitApp {
    return { ...this.constants_ }
  }

  public initApp() {
    this.httpClient.post<BaseResponse<InitApp>>(this.baseApiUrl + '/initApp', {})
      .subscribe( resp => {
        this.constants_ = resp.result
        this.store.dispatch( AttemptsActions.loadAttempts() )
      });
  }

}
