import { createAction, props } from "@ngrx/store";
import { Customer, Insured } from "../../interfaces";

export const loadInsurance = createAction(
  '[Dashboard Page] Load Insurance'
);

export const loadedInsurance = createAction(
  '[Dashboard Page] Loaded Insurance',
  props<{
    customer                  : Customer,
    maximumProtectionInsurance: Insured[],
    familyLifeInsurance       : Insured[],
    xsInsurance               : Insured[],
    oncologicalInsurance      : Insured[],
    sapInsurance              : Insured[]
  }>()
);

export const loadInsuranceFailure = createAction(
  '[Dashboard Page] Failure Insurance',
  props<{ httpStatus: number, error: string }>()
)

export const resetInsurance = createAction(
  '[Insurance Reset]'
)
