import { createReducer, on } from '@ngrx/store';
import { Customer, Insured } from '../../interfaces';
import { InsuredActions } from '..';

export const insuredActionReducerKey: string = 'insuredData';

export interface InsuredState {
  customer                  : Customer | null;
  maximumProtectionInsurance: Insured[];
  familyLifeInsurance       : Insured[];
  xsInsurance               : Insured[];
  oncologicalInsurance      : Insured[];
  sapInsurance              : Insured[];
  error                     : string | null;
}

const initInsuredState: InsuredState = {
  customer                  : null,
  maximumProtectionInsurance: [],
  familyLifeInsurance       : [],
  xsInsurance               : [],
  oncologicalInsurance      : [],
  sapInsurance              : [],
  error                     : null
}

export const insuredReducer = createReducer(
  initInsuredState,
  on( InsuredActions.loadInsurance, ( state ) => ({ ...state }) ),
  on( InsuredActions.loadedInsurance,
    ( state, { customer, maximumProtectionInsurance, familyLifeInsurance, xsInsurance, oncologicalInsurance ,sapInsurance} ) => ({
      ...state,
      customer,
      maximumProtectionInsurance,
      familyLifeInsurance,
      xsInsurance,
      oncologicalInsurance,
      sapInsurance
  }) ),
  on( InsuredActions.loadInsuranceFailure, ( state, { error } ) => ({ ...state, error }) ),
  on( InsuredActions.resetInsurance, ( state ) => ({
    ...state,
    client: null,
    maximumProtectionInsurance: [],
    familyLifeInsurance: [],
    xsInsurance: [],
    oncologicalInsurance: [],
    sapInsurance: [],
  }) )
)
