import { Injectable } from "@angular/core";
import { Actions, createEffect, ofType } from "@ngrx/effects";
import { mergeMap } from "rxjs";
import { map, tap } from "rxjs/operators";
import { LocalStorageService } from '../../services/local-storage.service';
import { TokenActions } from "..";
import { Router } from "@angular/router";
import { Store } from "@ngrx/store";
import { InsuredActions } from "src/app/dashboard/store";

@Injectable()
export class TokenEffects {

  constructor(
    private store: Store,
    private actions$: Actions,
    private router: Router,
    private localStorageService: LocalStorageService
  ) {}

  checkToken$ = createEffect(() => this.actions$.pipe(
    ofType( TokenActions.checkToken ),
    mergeMap( () => this.localStorageService.getObsLocalStorageFromKey(this.localStorageService.tokenStorageKey, true).pipe(
      map( (lsToken) => !lsToken ? TokenActions.removeToken() : TokenActions.saveToken({ token: lsToken.token }))
    ))
  ));

  saveToken$ = createEffect(() =>
    this.actions$.pipe(
      ofType(TokenActions.saveToken),
      tap(({ token }) => this.localStorageService.saveToLocalStorage(this.localStorageService.tokenStorageKey, { token }))
    ),
    { dispatch: false }
  );

  removeToken$ = createEffect(() =>
    this.actions$.pipe(
      ofType(TokenActions.removeToken),
      tap(() => {
        this.localStorageService.removeItemLocalStorage(this.localStorageService.tokenStorageKey);
        this.store.dispatch( InsuredActions.resetInsurance() );
        this.router.navigateByUrl('/verify-identity');
      })
    ),
    { dispatch: false }
  );


}
