import { createFeatureSelector, createSelector } from '@ngrx/store';
import { TokenReducer } from '..';

const tokenSelector = createFeatureSelector<TokenReducer.TokenState>(TokenReducer.actionReducerTokenKey);

export const token = createSelector(
  tokenSelector,
  ({ token }) => token
);

export const hasToken = createSelector(
  token,
  ( token ) => token ? true : false
);