import { createReducer, on } from '@ngrx/store'
import { AttemptsActions } from '../';

export const actionReducerAttemptsKey: string = 'attempts';

export interface AttemptsState {
  attempts: number;
  otpAttempts: number;
}

const initCounterState: AttemptsState = {
  attempts: 0,
  otpAttempts: 0
}

export const attemptsReducer = createReducer(
  initCounterState,
  on(AttemptsActions.loadAttempts, (state,) => ({
    ...state
  })),
  on(AttemptsActions.attemptsLoaded, (state, { attempts }) => ({
    ...state,
    attempts
  })),
  on(AttemptsActions.incremetAttempts, state => ({
    ...state,
    attempts: state.attempts + 1
  })),
  on(AttemptsActions.resetAttempts, state => ({
    ...state,
    attempts: 0
  })),
  on(AttemptsActions.incrementOtpAttempts, state => ({
    ...state,
    otpAttempts: state.otpAttempts + 1
  })),
  on(AttemptsActions.resetAttempts, state => ({
    ...state,
    otpAttempts: 0
  }))
);
