import { Injectable } from '@angular/core';
import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Observable } from 'rxjs';
import { delay, finalize } from 'rxjs/operators';
import { DialogService } from '../services/dialog.service';
import { Store } from '@ngrx/store';
import { LoaderActions } from '../store';

@Injectable({
  providedIn: 'root'
})
export class LoadingInterceptor implements HttpInterceptor {

  constructor(private dialogService: DialogService, private store: Store) {}

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    const dialogRef = this.dialogService.openLoader();
    this.store.dispatch( LoaderActions.showLoader() );
    return next.handle(req).pipe(
      finalize(() => {
        dialogRef.close()
        this.store.dispatch( LoaderActions.hideLoader() );
      })
    );
  }

}
