import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, Router, RouterStateSnapshot, UrlTree } from '@angular/router';
import { Store } from '@ngrx/store';
import { map, Observable, of, take } from 'rxjs';
import { CustomerActions } from '../verify-identity/store';
import { TokenActions, TokenSelectors } from '../shared/store';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard {

  constructor(private store: Store, private router: Router) { }

  canActivate(): Observable<boolean> {
    const userInfo = localStorage.getItem('userInfo');
    if (userInfo) {
      try {
        const { token } = JSON.parse(userInfo);
        if (token) {
          this.store.dispatch(TokenActions.saveToken({ token }));
          return of(true);
        }
      } catch (e) {
        console.error('Error parsing userInfo', e);
      }
    }


    return this.store.select(TokenSelectors.hasToken).pipe(
      take(1),
      map(hasToken => {
        if (hasToken) return true;
        this.router.navigate(['/verify-identity']);
        return false;
      })
    );
  }
}